import React, { useState } from 'react';
import { adminApi } from '../../utils/api';
import { useAdminNavigation } from '../../utils/navigation';

export default function AdminLoginScreen() {
  const navigation = useAdminNavigation();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (!email.trim() || !password.trim()) {
      setError('Email and Password required!');
      return;
    }
    setError('');
    setLoading(true);
    try {
      const r = await adminApi.post('/login', { email: email.trim(), password });
      localStorage.setItem('admin_token', r.data.token);
      navigation.replace('AdminDashboard');
    } catch {
      setError('Invalid credentials. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={s.root}>
      <form style={{ width: '100%', maxWidth: 420 }} onSubmit={submit}>
        {/* Logo */}
        <div style={s.logoWrap}>
          <div style={s.logoIcon}><span style={{ fontSize: 32 }}>🍎</span></div>
          <div style={s.logoText}>Fruites Admin</div>
          <div style={s.logoSub}>Management Portal</div>
        </div>

        {/* Card */}
        <div style={s.card}>
          <div style={s.eyebrow}>
            <div style={s.dot} />
            <span style={s.eyebrowTxt}>SECURE ACCESS</span>
          </div>

          <div style={s.title}>Admin Portal</div>
          <div style={s.sub}>Sign in to manage your store</div>

          {!!error && (
            <div style={s.errBox}><span style={s.errTxt}>⚠️  {error}</span></div>
          )}

          <div style={s.label}>EMAIL ADDRESS</div>
          <input
            style={s.input}
            placeholder="admin@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            type="email"
            autoCapitalize="none"
          />

          <div style={s.label}>PASSWORD</div>
          <input
            style={s.input}
            placeholder="••••••••••"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            type="password"
          />

          <button type="submit" style={{ ...s.btn, ...(loading ? { opacity: 0.7 } : {}) }} disabled={loading}>
            {loading ? 'Signing in…' : 'Sign In →'}
          </button>

          <div style={s.footer}>Protected by 256-bit SSL encryption</div>
        </div>
      </form>
    </div>
  );
}

const s = {
  root: {
    minHeight: '100vh', background: '#0a0e1a', display: 'flex', alignItems: 'center',
    justifyContent: 'center', padding: 24, fontFamily: 'system-ui, -apple-system, sans-serif',
  },
  logoWrap: { display: 'flex', flexDirection: 'column', alignItems: 'center', marginBottom: 32 },
  logoIcon: { width: 72, height: 72, background: '#16A34A', borderRadius: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 12 },
  logoText: { fontSize: 22, fontWeight: 900, color: '#fff', marginBottom: 4 },
  logoSub: { fontSize: 12, color: 'rgba(255,255,255,0.4)' },

  card: { width: '100%', background: 'rgba(255,255,255,0.05)', borderRadius: 24, padding: 28, border: '1px solid rgba(255,255,255,0.08)', boxSizing: 'border-box' },
  eyebrow: { display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16 },
  dot: { width: 7, height: 7, background: '#6358ff', borderRadius: 99 },
  eyebrowTxt: { fontSize: 10, fontWeight: 700, letterSpacing: 2, color: 'rgba(255,255,255,0.35)' },
  title: { fontSize: 28, fontWeight: 900, color: '#fff', marginBottom: 6 },
  sub: { fontSize: 13, color: 'rgba(255,255,255,0.35)', marginBottom: 24 },

  errBox: { background: 'rgba(220,38,38,0.1)', border: '1px solid rgba(220,38,38,0.25)', borderRadius: 10, padding: 12, marginBottom: 16 },
  errTxt: { color: '#fca5a5', fontSize: 13, fontWeight: 600 },

  label: { fontSize: 10, fontWeight: 700, letterSpacing: 1.8, color: 'rgba(255,255,255,0.3)', marginBottom: 8, marginTop: 4 },
  input: {
    width: '100%', boxSizing: 'border-box', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)',
    borderRadius: 12, padding: '14px 16px', fontSize: 15, color: '#fff', marginBottom: 16, outline: 'none',
  },

  btn: { width: '100%', background: '#6358ff', border: 'none', borderRadius: 12, padding: '15px 0', color: '#fff', fontSize: 15, fontWeight: 700, letterSpacing: 0.5, marginTop: 8, cursor: 'pointer' },
  footer: { textAlign: 'center', fontSize: 11, color: 'rgba(255,255,255,0.15)', marginTop: 20 },
};
