import React, { useEffect, useState, useCallback } from 'react';
import {
  BaggageClaim, Clock, CheckCircle2, Apple, Users, Bike, PlusCircle, UserPlus, Tag, Calendar,
} from 'lucide-react';
import AdminLayout from './AdminLayout';
import { adminApi } from '../../utils/api';
import { useAdminNavigation } from '../../utils/navigation';

const buildStatCards = (oStats, stats) => [
  { label: 'Total Orders',   value: oStats.total,              icon: BaggageClaim, color: '#22C55E', bg: '#DCFCE7' },
  { label: 'Active Orders',  value: oStats.active,             icon: Clock,        color: '#F59E0B', bg: '#FEF9C3' },
  { label: 'Delivered',      value: oStats.delivered,          icon: CheckCircle2, color: '#3B82F6', bg: '#DBEAFE' },
  { label: 'Products',       value: stats.total_products || 0, icon: Apple,        color: '#8B5CF6', bg: '#EDE9FE' },
  { label: 'Online Workers', value: stats.online_workers || 0, icon: Users,        color: '#EC4899', bg: '#FCE7F3' },
  { label: 'Busy Workers',   value: stats.busy_workers   || 0, icon: Bike,         color: '#EF4444', bg: '#FEE2E2' },
];

const QUICK_ACTIONS = [
  { screen: 'AdminOrders',     icon: BaggageClaim, label: 'Orders',      color: '#22C55E', bg: '#DCFCE7' },
  { screen: 'AdminBookings',   icon: Calendar,      label: 'Bookings',    color: '#3B82F6', bg: '#DBEAFE' },
  { screen: 'AdminProducts',   icon: Apple,         label: 'Products',    color: '#8B5CF6', bg: '#EDE9FE' },
  { screen: 'AdminWorkers',    icon: Users,         label: 'Workers',     color: '#F59E0B', bg: '#FEF9C3' },
  { screen: 'AdminAddProduct', icon: PlusCircle,    label: 'Add Product', color: '#EC4899', bg: '#FCE7F3' },
  { screen: 'AdminAddWorker',  icon: UserPlus,      label: 'Add Worker',  color: '#14B8A6', bg: '#CCFBF1' },
  { screen: 'AdminOffers',     icon: Tag,           label: 'Offers',      color: '#FF6B35', bg: '#FFF0EB' },
];

export default function AdminDashboardScreen() {
  const navigation = useAdminNavigation();
  const [stats, setStats] = useState({});
  const [oStats, setOStats] = useState({ total: 0, active: 0, delivered: 0 });
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      adminApi.get('/dashboard')
        .then((r) => setStats(r.data))
        .catch(() => navigation.replace('AdminLogin'));

      const ordersRes = await adminApi.get('/orders');
      const all = ordersRes.data || [];
      const active = all.filter((o) => o.status !== 'Delivered' && o.status !== 'Cancelled');
      const delivered = all.filter((o) => o.status === 'Delivered');
      setOStats({ total: all.length, active: active.length, delivered: delivered.length });
    } catch { /* noop, same as RN version */ }
    setLoading(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => { load(); }, [load]);

  const statCards = buildStatCards(oStats, stats);

  return (
    <AdminLayout activeScreen="AdminDashboard">
      <div style={{ padding: 16, paddingBottom: 40 }}>

        {/* Welcome banner */}
        <div style={s.welcome}>
          <div>
            <div style={s.welcomeTitle}>Welcome back, Admin! 👋</div>
            <div style={s.welcomeSub}>Here's what's happening with your store today.</div>
          </div>
          <span style={s.welcomeEmoji}>🍎</span>
        </div>

        <div style={s.sectionRow}>
          <span style={s.sectionTitle}>Overview</span>
          <div style={s.sectionLine} />
        </div>

        {loading ? (
          <div style={s.loadingWrap}>Loading…</div>
        ) : (
          <div style={s.statGrid}>
            {statCards.map((card) => {
              const Icon = card.icon;
              return (
                <div key={card.label} style={s.statCard}>
                  <div style={{ ...s.statIcon, background: card.bg }}>
                    <Icon size={22} color={card.color} />
                  </div>
                  <div>
                    <div style={s.statVal}>{card.value}</div>
                    <div style={s.statLbl}>{card.label}</div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        <div style={s.sectionRow}>
          <span style={s.sectionTitle}>Quick Actions</span>
          <div style={s.sectionLine} />
        </div>
        <div style={s.qaGrid}>
          {QUICK_ACTIONS.map((qa) => {
            const Icon = qa.icon;
            return (
              <button key={qa.screen} style={s.qaCard} onClick={() => navigation.navigate(qa.screen)}>
                <div style={{ ...s.qaIcon, background: qa.bg }}>
                  <Icon size={26} color={qa.color} />
                </div>
                <span style={s.qaLabel}>{qa.label}</span>
              </button>
            );
          })}
        </div>

      </div>
    </AdminLayout>
  );
}

const s = {
  welcome: {
    display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#22C55E',
    borderRadius: 20, padding: 22, marginBottom: 22, boxShadow: '0 8px 16px rgba(34,197,94,0.28)',
  },
  welcomeTitle: { fontSize: 18, fontWeight: 800, color: '#fff', marginBottom: 4 },
  welcomeSub: { fontSize: 13, color: 'rgba(255,255,255,0.85)' },
  welcomeEmoji: { fontSize: 52 },

  sectionRow: { display: 'flex', alignItems: 'center', marginBottom: 14, gap: 10 },
  sectionTitle: { fontSize: 12, fontWeight: 700, color: '#6B7280', letterSpacing: 0.9, textTransform: 'uppercase', whiteSpace: 'nowrap' },
  sectionLine: { flex: 1, height: 1, background: '#E5E7EB' },

  loadingWrap: { padding: '40px 0', textAlign: 'center', color: '#6B7280' },

  statGrid: { display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 24 },
  statCard: {
    display: 'flex', alignItems: 'center', gap: 14, background: '#fff', borderRadius: 16, padding: 16,
    width: 'calc(47.5% - 6px)', boxShadow: '0 2px 8px rgba(0,0,0,0.06)', border: '1px solid #F3F4F6', boxSizing: 'border-box',
  },
  statIcon: { width: 48, height: 48, borderRadius: 14, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 },
  statVal: { fontSize: 26, fontWeight: 800, color: '#111', lineHeight: '30px' },
  statLbl: { fontSize: 11, color: '#6B7280', fontWeight: 600, marginTop: 2 },

  qaGrid: { display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 16 },
  qaCard: {
    display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10, background: '#fff', borderRadius: 16,
    padding: 18, width: 'calc(30.5% - 8px)', boxShadow: '0 2px 8px rgba(0,0,0,0.06)', border: '1px solid #F3F4F6',
    cursor: 'pointer', boxSizing: 'border-box',
  },
  qaIcon: { width: 54, height: 54, borderRadius: 16, display: 'flex', alignItems: 'center', justifyContent: 'center' },
  qaLabel: { fontSize: 12, fontWeight: 700, color: '#1A1A1A', textAlign: 'center' },
};
