import React, { useState } from 'react';
import { ArrowLeft } from 'lucide-react';
import { adminApi } from '../../utils/api';
import { useAdminNavigation } from '../../utils/navigation';

const FIELDS = [
  { label: 'Full Name *', key: 'name', placeholder: 'e.g. Ravi Kumar' },
  { label: 'Phone *', key: 'phone', placeholder: 'e.g. 9876543210', keyboard: 'tel' },
  { label: 'Password *', key: 'password', placeholder: 'Strong password', secure: true },
];

export default function AdminAddWorkerScreen() {
  const navigation = useAdminNavigation();
  const [form, setForm] = useState({ name: '', phone: '', password: '' });
  const [saving, setSaving] = useState(false);

  const update = (key, val) => setForm((p) => ({ ...p, [key]: val }));

  const handleSave = async (e) => {
    e.preventDefault();
    if (!form.name.trim() || !form.phone.trim() || !form.password.trim()) {
      window.alert('Name, Phone, Password అన్నీ required!');
      return;
    }
    setSaving(true);
    try {
      await adminApi.post('/workers', form);
      window.alert('✅ Worker added!');
      navigation.goBack();
    } catch (e2) {
      window.alert(e2?.response?.data?.detail || 'Failed to add worker');
    } finally { setSaving(false); }
  };

  return (
    <div style={{ minHeight: '100vh', background: '#F8F9FA' }}>
      <div style={s.header}>
        <button style={s.backBtn} onClick={() => navigation.goBack()}>
          <ArrowLeft size={20} color="#fff" />
        </button>
        <div>
          <div style={s.headerTitle}>👷 Add Worker</div>
          <div style={s.headerSub}>New delivery captain add చేయండి</div>
        </div>
      </div>

      <form onSubmit={handleSave} style={{ padding: 16, paddingBottom: 40 }}>
        <div style={s.card}>
          {FIELDS.map((field) => (
            <div key={field.key} style={{ marginBottom: 16 }}>
              <label style={s.label}>{field.label}</label>
              <input
                style={s.input}
                type={field.secure ? 'password' : (field.keyboard || 'text')}
                placeholder={field.placeholder}
                value={form[field.key]}
                onChange={(e) => update(field.key, e.target.value)}
              />
            </div>
          ))}

          <div style={s.infoBox}>
            <span style={s.infoTxt}>ℹ️ Worker ఈ phone + password తో login చేస్తాడు</span>
          </div>

          <button type="submit" style={{ ...s.saveBtn, ...(saving ? { opacity: 0.7 } : {}) }} disabled={saving}>
            {saving ? 'Saving…' : '💾 Add Worker'}
          </button>
        </div>
      </form>
    </div>
  );
}

const s = {
  header: { background: '#F59E0B', padding: '16px 16px', display: 'flex', alignItems: 'center', gap: 12 },
  backBtn: { width: 38, height: 38, background: 'rgba(255,255,255,0.2)', border: 'none', borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' },
  headerTitle: { fontSize: 17, fontWeight: 900, color: '#fff' },
  headerSub: { fontSize: 11, color: 'rgba(255,255,255,0.8)' },
  card: { background: '#fff', borderRadius: 16, padding: 16, boxShadow: '0 2px 6px rgba(0,0,0,0.06)', maxWidth: 480, margin: '0 auto' },
  label: { fontSize: 12, fontWeight: 700, color: '#374151', marginBottom: 6, display: 'block' },
  input: { width: '100%', boxSizing: 'border-box', background: '#F9FAFB', borderRadius: 10, padding: '12px 14px', fontSize: 14, color: '#111', border: '1px solid #E5E7EB', outline: 'none' },
  infoBox: { background: '#EFF6FF', borderRadius: 10, padding: 12, marginBottom: 16, border: '1px solid #BFDBFE' },
  infoTxt: { fontSize: 13, color: '#1D4ED8', fontWeight: 600 },
  saveBtn: { width: '100%', background: '#F59E0B', border: 'none', borderRadius: 12, padding: '15px 0', color: '#fff', fontSize: 15, fontWeight: 900, cursor: 'pointer' },
};
