import React, { useEffect, useState, useCallback } from 'react';
import { Plus, Phone, Trash2 } from 'lucide-react';
import AdminLayout from './AdminLayout';
import { adminApi } from '../../utils/api';
import { useAdminNavigation } from '../../utils/navigation';

export default function AdminWorkersScreen() {
  const navigation = useAdminNavigation();
  const [workers, setWorkers] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const r = await adminApi.get('/workers');
      setWorkers(r.data || []);
    } catch { /* noop */ }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleDelete = (id) => {
    if (!window.confirm('ఈ worker delete చేయాలా?')) return;
    adminApi.delete(`/workers/${id}`).then(load).catch(() => window.alert('Delete failed'));
  };

  const onlineWorkers = workers.filter((w) => w.is_active);
  const busyWorkers = workers.filter((w) => w.is_busy);

  return (
    <AdminLayout activeScreen="AdminWorkers">
      {loading ? (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%' }}>Loading…</div>
      ) : (
        <div style={{ padding: 16, paddingBottom: 40 }}>
          <div style={s.pageHeader}>
            <div style={s.pageTitle}>👷 Workers ({workers.length})</div>
            <button style={s.addBtn} onClick={() => navigation.navigate('AdminAddWorker')}>
              <Plus size={18} color="#fff" />
              <span style={s.addBtnTxt}>Add</span>
            </button>
          </div>

          <div style={s.statsRow}>
            {[
              { label: 'Total', value: workers.length, color: '#6366f1' },
              { label: 'Online', value: onlineWorkers.length, color: '#10b981' },
              { label: 'Busy', value: busyWorkers.length, color: '#f59e0b' },
              { label: 'Offline', value: workers.length - onlineWorkers.length, color: '#94a3b8' },
            ].map((st) => (
              <div key={st.label} style={{ ...s.statCard, borderLeftColor: st.color }}>
                <div style={s.statVal}>{st.value}</div>
                <div style={s.statLbl}>{st.label}</div>
              </div>
            ))}
          </div>

          {workers.length === 0 ? (
            <div style={s.empty}>
              <div style={{ fontSize: 40 }}>👷</div>
              <div style={s.emptyTxt}>No workers yet</div>
            </div>
          ) : workers.map((w) => (
            <div key={w.id} style={s.card}>
              <div style={{ ...s.avatar, background: w.is_active ? '#DCFCE7' : '#F3F4F6' }}>
                <span style={{ ...s.avatarTxt, color: w.is_active ? '#166534' : '#9CA3AF' }}>
                  {w.name?.[0]?.toUpperCase() || 'W'}
                </span>
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={s.workerName}>{w.name}</span>
                  <div style={{ display: 'flex', gap: 6 }}>
                    {w.is_active && (
                      <div style={s.onlineBadge}>
                        <div style={s.onlineDot} />
                        <span style={s.onlineTxt}>Online</span>
                      </div>
                    )}
                    {w.is_busy && (
                      <div style={s.busyBadge}><span style={s.busyTxt}>Busy</span></div>
                    )}
                  </div>
                </div>
                <div style={s.row}>
                  <Phone size={12} color="#9CA3AF" />
                  <span style={s.workerPhone}>{w.phone}</span>
                </div>
                <div style={s.cardActions}>
                  <button style={s.deleteBtn} onClick={() => handleDelete(w.id)}>
                    <Trash2 size={13} color="#EF4444" />
                    <span style={s.deleteBtnTxt}>Delete</span>
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </AdminLayout>
  );
}

const s = {
  pageHeader: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 },
  pageTitle: { fontSize: 18, fontWeight: 800, color: '#111' },
  addBtn: { display: 'flex', alignItems: 'center', gap: 4, background: '#22C55E', border: 'none', borderRadius: 10, padding: '8px 14px', cursor: 'pointer' },
  addBtnTxt: { color: '#fff', fontSize: 13, fontWeight: 700 },
  statsRow: { display: 'flex', gap: 10, marginBottom: 20, flexWrap: 'wrap' },
  statCard: { flex: '1 1 100px', background: '#fff', borderRadius: 12, padding: 12, borderLeft: '4px solid', boxShadow: '0 2px 6px rgba(0,0,0,0.05)' },
  statVal: { fontSize: 22, fontWeight: 900, color: '#111' },
  statLbl: { fontSize: 9, fontWeight: 700, color: '#64748B', textTransform: 'uppercase', marginTop: 2 },
  card: { background: '#fff', borderRadius: 14, padding: 14, marginBottom: 10, boxShadow: '0 2px 6px rgba(0,0,0,0.05)', display: 'flex', gap: 12, border: '1px solid #F3F4F6' },
  avatar: { width: 52, height: 52, borderRadius: 14, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 },
  avatarTxt: { fontSize: 22, fontWeight: 900 },
  workerName: { fontSize: 15, fontWeight: 800, color: '#111' },
  row: { display: 'flex', alignItems: 'center', gap: 5, marginTop: 4 },
  workerPhone: { fontSize: 12, color: '#6B7280' },
  onlineBadge: { display: 'flex', alignItems: 'center', gap: 4, background: '#DCFCE7', borderRadius: 6, padding: '3px 8px' },
  onlineDot: { width: 6, height: 6, borderRadius: 99, background: '#22C55E' },
  onlineTxt: { fontSize: 10, fontWeight: 700, color: '#166534' },
  busyBadge: { background: '#FEF9C3', borderRadius: 6, padding: '3px 8px' },
  busyTxt: { fontSize: 10, fontWeight: 700, color: '#854D0E' },
  cardActions: { display: 'flex', gap: 8, marginTop: 10 },
  deleteBtn: { display: 'flex', alignItems: 'center', gap: 4, background: '#FEE2E2', border: 'none', borderRadius: 8, padding: '6px 10px', cursor: 'pointer' },
  deleteBtnTxt: { fontSize: 12, color: '#EF4444', fontWeight: 700 },
  empty: { textAlign: 'center', padding: 40, background: '#fff', borderRadius: 14 },
  emptyTxt: { fontSize: 15, color: '#9CA3AF', marginTop: 8 },
};
