import React, { useEffect } from 'react';
import {
  Gauge, ShoppingBag, Calendar, Apple, Users, Tag, UsersRound, LogOut,
} from 'lucide-react';
import { useAdminNavigation } from '../../utils/navigation';
import { getSocket } from '../../utils/socket';

const NAV_ITEMS = [
  { screen: 'AdminDashboard', icon: Gauge,       label: 'Dashboard' },
  { screen: 'AdminOrders',    icon: ShoppingBag, label: 'Orders' },
  { screen: 'AdminBookings',  icon: Calendar,    label: 'Bookings' },
  { screen: 'AdminProducts',  icon: Apple,       label: 'Products' },
  { screen: 'AdminWorkers',   icon: Users,       label: 'Workers' },
  { screen: 'AdminOffers',    icon: Tag,         label: 'Offers' },
  { screen: 'AdminCRM',       icon: UsersRound,  label: 'CRM' },
];

export default function AdminLayout({ children, activeScreen, title, onNewBooking }) {
  const navigation = useAdminNavigation();

  // Same socket alerts as the RN version, just using window.alert-style
  // confirm dialogs instead of RN's Alert.alert.
  useEffect(() => {
    let socket;

    async function setupSocket() {
      try {
        socket = getSocket();
        if (!socket) return;

        socket.on('new_booking_alert', (data) => {
          const open = window.confirm(`🚗 New Booking!\nService: ${data.service}\nID: #${data.id}\n\nOpen Bookings?`);
          if (open) {
            navigation.navigate('AdminBookings');
            if (onNewBooking) onNewBooking();
          }
        });

        socket.on('new_order_alert', (data) => {
          const open = window.confirm(`🛒 New Order!\nCustomer: ${data.user}\nTotal: ₹${data.total}\n\nView Orders?`);
          if (open) navigation.navigate('AdminOrders');
        });
      } catch (e) {
        console.log('Socket setup error:', e);
      }
    }

    setupSocket();

    return () => {
      if (socket) {
        socket.off('new_booking_alert');
        socket.off('new_order_alert');
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const logout = () => {
    localStorage.removeItem('admin_token');
    navigation.replace('AdminLogin');
  };

  const pageTitle = NAV_ITEMS.find((n) => n.screen === activeScreen)?.label || title || 'Dashboard';

  return (
    <div style={s.page}>
      {/* Top bar */}
      <div style={s.topbar}>
        <div style={s.topbarLeft}>
          <div style={s.logoIcon}><span style={{ fontSize: 18 }}>🍎</span></div>
          <div>
            <div style={s.logoText}>GrabZomart Admin</div>
            <div style={s.logoSub}>{pageTitle}</div>
          </div>
        </div>
        <button style={s.logoutBtn} onClick={logout}>
          <LogOut size={16} color="#EF4444" />
          <span style={s.logoutTxt}>Logout</span>
        </button>
      </div>

      {/* Content */}
      <div style={s.content}>{children}</div>

      {/* Bottom nav */}
      <div style={s.bottomNav}>
        <div style={s.navScroll}>
          {NAV_ITEMS.map((item) => {
            const active = activeScreen === item.screen;
            const Icon = item.icon;
            return (
              <button
                key={item.screen}
                style={s.navItem}
                onClick={() => navigation.navigate(item.screen)}
              >
                <div style={{ ...s.navIconWrap, ...(active ? s.navIconWrapActive : {}) }}>
                  <Icon size={22} color={active ? '#111' : '#B0B7C3'} />
                </div>
                <span style={{ ...s.navLabel, ...(active ? s.navLabelActive : {}) }}>
                  {item.label}
                </span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

const s = {
  page: { display: 'flex', flexDirection: 'column', height: '100vh', background: '#F8F9FA', fontFamily: 'system-ui, -apple-system, sans-serif' },

  topbar: {
    background: '#fff', padding: '14px 16px', display: 'flex', alignItems: 'center',
    justifyContent: 'space-between', borderBottom: '1px solid #F0F0F0',
    boxShadow: '0 1px 4px rgba(0,0,0,0.04)', flexShrink: 0,
  },
  topbarLeft: { display: 'flex', alignItems: 'center', gap: 10 },
  logoIcon: { width: 38, height: 38, background: '#111', borderRadius: 11, display: 'flex', alignItems: 'center', justifyContent: 'center' },
  logoText: { fontSize: 14, fontWeight: 800, color: '#111' },
  logoSub: { fontSize: 11, color: '#9CA3AF', marginTop: 1 },
  logoutBtn: { display: 'flex', alignItems: 'center', gap: 5, background: '#FEF2F2', border: 'none', borderRadius: 8, padding: '7px 12px', cursor: 'pointer' },
  logoutTxt: { color: '#EF4444', fontSize: 12, fontWeight: 700 },

  content: { flex: 1, overflowY: 'auto' },

  bottomNav: {
    background: '#fff', borderTop: '1px solid #F0F0F0', paddingTop: 8, paddingBottom: 12,
    boxShadow: '0 -3px 12px rgba(0,0,0,0.06)', flexShrink: 0,
  },
  navScroll: { display: 'flex', overflowX: 'auto', padding: '0 4px', gap: 2 },
  navItem: {
    display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
    gap: 3, padding: '6px 10px', minWidth: 64, background: 'none', border: 'none', cursor: 'pointer',
  },
  navIconWrap: { width: 44, height: 32, display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 10 },
  navIconWrapActive: { background: '#F3F4F6' },
  navLabel: { fontSize: 10, color: '#B0B7C3', fontWeight: 600 },
  navLabelActive: { color: '#111', fontWeight: 700 },
};
