import React from 'react';

const CATS = ['Fruits', 'Vegetables', 'Dry Fruits', 'Exotic', 'Other'];

const FIELDS = [
  { label: 'Product Name *', key: 'name', placeholder: 'e.g. Fresh Mango' },
  { label: 'Price (₹) *', key: 'price', placeholder: 'e.g. 80', keyboard: 'number' },
  { label: 'Original Price (₹)', key: 'original_price', placeholder: 'e.g. 100', keyboard: 'number' },
  { label: 'Unit', key: 'unit', placeholder: 'e.g. kg' },
  { label: 'Stock', key: 'stock', placeholder: 'e.g. 100', keyboard: 'number' },
  { label: 'Image URL', key: 'image', placeholder: 'https://...' },
  { label: 'Description', key: 'description', placeholder: 'Product description...', multiline: true },
];

export default function ProductFormFields({ form, update, accent }) {
  return (
    <>
      {FIELDS.map((field) => (
        <div key={field.key} style={{ marginBottom: 14 }}>
          <label style={s.label}>{field.label}</label>
          {field.multiline ? (
            <textarea
              style={{ ...s.input, height: 80, resize: 'vertical' }}
              placeholder={field.placeholder}
              value={form[field.key]}
              onChange={(e) => update(field.key, e.target.value)}
            />
          ) : (
            <input
              style={s.input}
              type={field.keyboard || 'text'}
              placeholder={field.placeholder}
              value={form[field.key]}
              onChange={(e) => update(field.key, e.target.value)}
            />
          )}
        </div>
      ))}

      <label style={s.label}>Category</label>
      <div style={s.catRow}>
        {CATS.map((c) => (
          <button
            type="button"
            key={c}
            onClick={() => update('category', c)}
            style={{
              ...s.catBtn,
              ...(form.category === c ? { background: accent, borderColor: accent, color: '#fff' } : {}),
            }}
          >
            {c}
          </button>
        ))}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 14, marginBottom: 20 }}>
        <span style={s.label}>Active</span>
        <button
          type="button"
          onClick={() => update('is_active', !form.is_active)}
          style={{ ...s.toggle, background: form.is_active ? '#22C55E' : '#9CA3AF' }}
        >
          {form.is_active ? '✅ Active' : '❌ Inactive'}
        </button>
      </div>
    </>
  );
}

const s = {
  label: { fontSize: 12, fontWeight: 700, color: '#374151', marginBottom: 6, display: 'block' },
  input: {
    width: '100%', boxSizing: 'border-box', background: '#F9FAFB', borderRadius: 10, padding: '12px 14px',
    fontSize: 14, color: '#111', border: '1px solid #E5E7EB', outline: 'none', fontFamily: 'inherit',
  },
  catRow: { display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 14 },
  catBtn: {
    padding: '8px 16px', borderRadius: 99, border: '1.5px solid #E5E7EB', background: '#fff',
    fontSize: 13, fontWeight: 700, color: '#6B7280', cursor: 'pointer',
  },
  toggle: { border: 'none', borderRadius: 8, padding: '8px 14px', color: '#fff', fontSize: 12, fontWeight: 700, cursor: 'pointer' },
};
