import { Search, XCircle, Info, Pencil, X } from 'lucide-react';
import AdminLayout from './AdminLayout';
import WhatsAppIcon from '../../components/WhatsAppIcon';
import { adminApi } from '../../utils/api';

const DEFAULT_TEMPLATES = [
  {
    id: 1,
    name: '🎉 New Offer',
    text: `Hello {name}! 👋

🎉 *Special Offer Just for You!*

🛒 Shop fresh fruits & vegetables at amazing prices!
🏷️ Use code: *SAVE20* to get *20% OFF*

🚀 Order now & get delivery at your doorstep!

👉 Open App & Order Now!

_Fruites Bazzar Team_ 🍎`,
  },
  {
    id: 2,
    name: '🍎 New Arrivals',
    text: `Hello {name}! 👋

🍎 *Fresh Stock Available Now!*

✅ Fresh Mangoes
✅ Organic Vegetables  
✅ Exotic Fruits

🚚 Fast delivery to your door!
💰 Best prices guaranteed!

Order now on our app! 🛒

_Fruites Bazzar_ 🌿`,
  },
  {
    id: 3,
    name: '💰 Flash Sale',
    text: `Hello {name}! 🔥

⚡ *FLASH SALE — Today Only!*

🥭 Mangoes — 20% OFF
🍇 Grapes — 15% OFF
🥦 Vegetables — 10% OFF

⏰ Limited time offer!
🛒 Order before midnight!

_Fruites Bazzar Team_ 🍎`,
  },
  {
    id: 4,
    name: '🙏 Thank You',
    text: `Hello {name}! 🙏

Thank you for shopping with *Fruites Bazzar!* 🍎

We hope you enjoyed our fresh products.

⭐ Please rate us & share with friends!
🎁 Refer a friend & get *₹50 OFF* on next order!

See you again soon! 😊

_Fruites Bazzar Team_`,
  },
];

export default function AdminCRMScreen() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [templates, setTemplates] = useState(DEFAULT_TEMPLATES);
  const [selectedTpl, setSelectedTpl] = useState(DEFAULT_TEMPLATES[0]);
  const [editingTpl, setEditingTpl] = useState(null);
  const [editText, setEditText] = useState('');
  const [editName, setEditName] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [searchTxt, setSearchTxt] = useState('');

  const load = useCallback(async () => {
    try {
      const r = await adminApi.get('/users');
      setUsers(r.data || []);
    } catch { window.alert('Failed to load users'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const sendToUser = (user) => {
    if (!user?.phone) { window.alert('Phone number not available'); return; }
    const message = selectedTpl.text.replace(/{name}/g, user.name || 'Sir/Madam');
    const phone = user.phone.replace(/[^0-9]/g, '');
    const url = `https://wa.me/91${phone}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const sendToAll = () => {
    if (filteredUsers.length === 0) { window.alert('Users list empty'); return; }
    const ok = window.confirm(`${filteredUsers.length} users కి WhatsApp message పంపాలా?\n\nప్రతి user కి manually send చేయాలి.`);
    if (ok) sendNextUser(0);
  };

  const sendNextUser = (index) => {
    if (index >= filteredUsers.length) { window.alert('✅ Done! All users కి messages పంపారు!'); return; }
    const user = filteredUsers[index];
    const message = selectedTpl.text.replace(/{name}/g, user.name || 'Sir/Madam');
    const phone = (user.phone || '').replace(/[^0-9]/g, '');
    const url = `https://wa.me/91${phone}?text=${encodeURIComponent(message)}`;

    const send = window.confirm(`📤 ${index + 1}/${filteredUsers.length}\n${user.name} (${user.phone}) కి పంపాలా?\n\nOK = Send & Next, Cancel = Skip`);
    if (send) window.open(url, '_blank');
    setTimeout(() => sendNextUser(index + 1), send ? 1500 : 0);
  };

  const openEditModal = (tpl) => {
    setEditText(tpl.text);
    setEditName(tpl.name);
    setEditingTpl(tpl);
    setModalVisible(true);
  };

  const saveTemplate = () => {
    const updated = templates.map((t) => (t.id === editingTpl.id ? { ...t, name: editName, text: editText } : t));
    setTemplates(updated);
    if (selectedTpl.id === editingTpl.id) setSelectedTpl({ ...editingTpl, name: editName, text: editText });
    setModalVisible(false);
  };

  const filteredUsers = users.filter(
    (u) => u.name?.toLowerCase().includes(searchTxt.toLowerCase()) || u.phone?.includes(searchTxt)
  );

  return (
    <AdminLayout activeScreen="AdminCRM">
      {loading ? (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%' }}>Loading…</div>
      ) : (
        <div style={{ padding: 16, paddingBottom: 40, maxWidth: 720, margin: '0 auto' }}>
          <div style={s.pageHeader}>
            <div>
              <div style={s.pageTitle}>👥 CRM</div>
              <div style={s.pageSubtitle}>{users.length} customers</div>
            </div>
            <button style={s.sendAllBtn} onClick={sendToAll}>
              <WhatsAppIcon size={16} />
              <span style={s.sendAllTxt}>Send All</span>
            </button>
          </div>

          <div style={s.sectionTitle}>📋 Template Select చేయండి</div>
          <div style={s.tplRow}>
            {templates.map((tpl) => (
              <button
                key={tpl.id}
                style={{ ...s.tplChip, ...(selectedTpl.id === tpl.id ? { background: '#25D366', borderColor: '#25D366', color: '#fff' } : {}) }}
                onClick={() => setSelectedTpl(tpl)}
              >
                {tpl.name}
              </button>
            ))}
          </div>

          <div style={s.tplPreviewCard}>
            <div style={s.tplPreviewHeader}>
              <span style={s.tplPreviewTitle}>👁️ Preview</span>
              <button style={s.editTplBtn} onClick={() => openEditModal(selectedTpl)}>
                <Pencil size={13} color="#3B82F6" />
                <span style={s.editTplBtnTxt}>Edit</span>
              </button>
            </div>
            <div style={s.tplPreviewTxt}>{selectedTpl.text.replace(/{name}/g, 'Customer')}</div>
            <div style={s.tplHint}>
              <Info size={13} color="#6B7280" />
              <span style={s.tplHintTxt}>{'{name}'} automatically replace అవుతుంది</span>
            </div>
          </div>

          <div style={s.searchBar}>
            <Search size={16} color="#9CA3AF" />
            <input
              style={s.searchInput}
              placeholder="Search by name or phone..."
              value={searchTxt}
              onChange={(e) => setSearchTxt(e.target.value)}
            />
            {searchTxt.length > 0 && (
              <button style={s.clearBtn} onClick={() => setSearchTxt('')}>
                <XCircle size={16} color="#9CA3AF" />
              </button>
            )}
          </div>

          <div style={s.sectionTitle}>👥 Customers ({filteredUsers.length})</div>

          {filteredUsers.length === 0 ? (
            <div style={s.empty}>
              <div style={{ fontSize: 40 }}>👥</div>
              <div style={s.emptyTxt}>No customers found</div>
            </div>
          ) : filteredUsers.map((u) => (
            <div key={u.id} style={s.userCard}>
              <div style={s.avatar}><span style={s.avatarTxt}>{u.name?.[0]?.toUpperCase() || '?'}</span></div>
              <div style={{ flex: 1 }}>
                <div style={s.userName}>{u.name || 'Unknown'}</div>
                <div style={s.userPhone}>{u.phone}</div>
              </div>
              <button style={s.waBtn} onClick={() => sendToUser(u)}>
                <WhatsAppIcon size={20} />
              </button>
            </div>
          ))}
        </div>
      )}

      {modalVisible && (
        <div style={s.modalOverlay} onClick={() => setModalVisible(false)}>
          <div style={s.modalCard} onClick={(e) => e.stopPropagation()}>
            <div style={s.modalHeader}>
              <span style={s.modalTitle}>✏️ Template Edit</span>
              <button style={s.closeBtn} onClick={() => setModalVisible(false)}><X size={22} color="#111" /></button>
            </div>

            <label style={s.label}>Template Name</label>
            <input style={s.input} value={editName} onChange={(e) => setEditName(e.target.value)} placeholder="Template name..." />

            <label style={s.label}>Message ({'{name}'} వాడవచ్చు)</label>
            <textarea style={s.textArea} value={editText} onChange={(e) => setEditText(e.target.value)} placeholder="Message text..." />

            <button style={s.saveBtn} onClick={saveTemplate}>💾 Save Template</button>
          </div>
        </div>
      )}
    </AdminLayout>
  );
}

const s = {
  pageHeader: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 },
  pageTitle: { fontSize: 18, fontWeight: 800, color: '#111' },
  pageSubtitle: { fontSize: 12, color: '#6B7280', marginTop: 2 },
  sendAllBtn: { display: 'flex', alignItems: 'center', gap: 6, background: '#25D366', border: 'none', borderRadius: 10, padding: '9px 14px', cursor: 'pointer' },
  sendAllTxt: { color: '#fff', fontSize: 13, fontWeight: 700 },
  sectionTitle: { fontSize: 13, fontWeight: 800, color: '#374151', marginBottom: 10, marginTop: 4 },
  tplRow: { display: 'flex', gap: 8, marginBottom: 12, overflowX: 'auto' },
  tplChip: { padding: '8px 14px', borderRadius: 99, border: '1.5px solid #E5E7EB', background: '#fff', fontSize: 12, fontWeight: 700, color: '#6B7280', cursor: 'pointer', whiteSpace: 'nowrap' },
  tplPreviewCard: { background: '#F0FDF4', borderRadius: 14, padding: 14, marginBottom: 16, border: '1px solid #BBF7D0' },
  tplPreviewHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 },
  tplPreviewTitle: { fontSize: 12, fontWeight: 800, color: '#166534' },
  editTplBtn: { display: 'flex', alignItems: 'center', gap: 4, background: '#EFF6FF', border: 'none', borderRadius: 8, padding: '5px 10px', cursor: 'pointer' },
  editTplBtnTxt: { fontSize: 11, color: '#3B82F6', fontWeight: 700 },
  tplPreviewTxt: { fontSize: 13, color: '#374151', lineHeight: '20px', whiteSpace: 'pre-wrap' },
  tplHint: { display: 'flex', alignItems: 'center', gap: 4, marginTop: 10 },
  tplHintTxt: { fontSize: 11, color: '#6B7280' },
  searchBar: { display: 'flex', alignItems: 'center', background: '#fff', borderRadius: 12, padding: '10px 12px', gap: 8, border: '1px solid #E5E7EB', marginBottom: 14, boxShadow: '0 1px 3px rgba(0,0,0,0.04)' },
  searchInput: { flex: 1, fontSize: 14, color: '#111', border: 'none', outline: 'none' },
  clearBtn: { background: 'none', border: 'none', cursor: 'pointer', display: 'flex' },
  userCard: { background: '#fff', borderRadius: 12, padding: 12, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 12, boxShadow: '0 2px 6px rgba(0,0,0,0.05)', border: '1px solid #F3F4F6' },
  avatar: { width: 44, height: 44, borderRadius: 14, background: '#25D366', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 },
  avatarTxt: { color: '#fff', fontSize: 18, fontWeight: 900 },
  userName: { fontSize: 14, fontWeight: 800, color: '#111' },
  userPhone: { fontSize: 12, color: '#6B7280', marginTop: 2 },
  waBtn: { width: 44, height: 44, borderRadius: 12, background: '#25D366', border: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 2px 6px rgba(0,0,0,0.1)', cursor: 'pointer', flexShrink: 0 },
  empty: { textAlign: 'center', padding: 40, background: '#fff', borderRadius: 14 },
  emptyTxt: { fontSize: 15, color: '#9CA3AF', marginTop: 8 },
  modalOverlay: { position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 100 },
  modalCard: { width: '100%', maxWidth: 560, background: '#fff', borderTopLeftRadius: 24, borderTopRightRadius: 24, padding: 20, maxHeight: '85vh', overflowY: 'auto', boxSizing: 'border-box' },
  modalHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 },
  modalTitle: { fontSize: 16, fontWeight: 800, color: '#111' },
  closeBtn: { background: 'none', border: 'none', cursor: 'pointer', display: 'flex' },
  label: { fontSize: 12, fontWeight: 700, color: '#374151', marginBottom: 6, display: 'block' },
  input: { width: '100%', boxSizing: 'border-box', background: '#F9FAFB', borderRadius: 10, padding: '11px 14px', fontSize: 14, color: '#111', border: '1px solid #E5E7EB', marginBottom: 14, outline: 'none' },
  textArea: { width: '100%', boxSizing: 'border-box', background: '#F9FAFB', borderRadius: 10, padding: '11px 14px', fontSize: 13, color: '#111', border: '1px solid #E5E7EB', height: 220, marginBottom: 16, outline: 'none', resize: 'vertical', fontFamily: 'inherit' },
  saveBtn: { width: '100%', background: '#25D366', border: 'none', borderRadius: 12, padding: '14px 0', color: '#fff', fontSize: 15, fontWeight: 900, cursor: 'pointer' },
};
