import React, { useEffect, useState } from 'react';
import { Plus, Tag, ChevronUp, ChevronDown, Rocket, Trash2 } from 'lucide-react';
import AdminLayout from './AdminLayout';
import { adminApi } from '../../utils/api';

const OG = '#FF6B35';
const OG_LIGHT = '#FFF5F0';
const OG_BORD = '#FFE4D6';

function OfferCard({ item, onDelete }) {
  const isPercent = item.discount_type === 'percent';
  const discLabel = isPercent ? `${item.discount_value}%` : `₹${item.discount_value}`;

  return (
    <div style={oc.card}>
      <div style={oc.left}>
        <div style={oc.codePill}><span style={oc.codeText}>{item.code}</span></div>
        <div style={oc.title}>{item.title}</div>
        {item.min_order > 0 && <div style={oc.meta}>Min ₹{item.min_order}</div>}
      </div>

      <div style={oc.discWrap}>
        <div style={oc.discVal}>{discLabel}</div>
        <div style={oc.discLbl}>OFF</div>
      </div>

      <button style={oc.del} onClick={() => onDelete(item.id)}>
        <Trash2 size={15} color="#EF4444" />
      </button>
    </div>
  );
}

function Field({ label, value, onChange, placeholder, keyboardType = 'text', autoCapitalize }) {
  return (
    <div style={f.wrap}>
      <label style={f.label}>{label}</label>
      <input
        style={f.input}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        type={keyboardType}
        autoCapitalize={autoCapitalize}
      />
    </div>
  );
}

export default function AdminOffersScreen() {
  const [offers, setOffers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [formOpen, setFormOpen] = useState(true);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [code, setCode] = useState('');
  const [discountType, setDiscountType] = useState('percent');
  const [discountValue, setDiscountValue] = useState('');
  const [minOrder, setMinOrder] = useState('');
  const [maxDiscount, setMaxDiscount] = useState('');

  useEffect(() => { load(); }, []);

  const load = async () => {
    try {
      const r = await adminApi.get('/offers');
      setOffers(r.data);
    } catch { window.alert('Failed to load offers'); }
    finally { setLoading(false); }
  };

  const reset = () => {
    setTitle(''); setDescription(''); setCode('');
    setDiscountValue(''); setMinOrder(''); setMaxDiscount('');
    setDiscountType('percent');
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    if (!title.trim() || !code.trim() || !discountValue.trim()) {
      window.alert('Title, Code, Discount value fill చేయండి!');
      return;
    }
    setSaving(true);
    try {
      const r = await adminApi.post('/offers', {
        title: title.trim(),
        description: description.trim(),
        code: code.trim().toUpperCase(),
        discount_type: discountType,
        discount_value: parseFloat(discountValue),
        min_order: parseFloat(minOrder || '0'),
        max_discount: parseFloat(maxDiscount || '0'),
      });
      window.alert(`✅ Done! ${r.data.notified} users కి notification వెళ్ళింది!`);
      reset();
      load();
    } catch (e2) {
      window.alert(e2?.response?.data?.detail || 'Failed');
    } finally { setSaving(false); }
  };

  const handleDelete = (id) => {
    if (!window.confirm('Offer delete చేయాలా?')) return;
    adminApi.delete(`/offers/${id}`).then(load).catch(() => window.alert('Delete failed'));
  };

  return (
    <AdminLayout activeScreen="AdminOffers">
      <div style={{ padding: 14, paddingBottom: 60, maxWidth: 640, margin: '0 auto' }}>

        <div style={s.card}>
          <button type="button" style={s.cardHead} onClick={() => setFormOpen((p) => !p)}>
            <div style={s.cardHeadLeft}>
              <div style={s.headIcon}><Plus size={18} color={OG} /></div>
              <div>
                <div style={s.cardTitle}>New Offer</div>
                <div style={s.cardSub}>Create చేస్తే auto notify అవుతుంది</div>
              </div>
            </div>
            {formOpen ? <ChevronUp size={18} color="#9CA3AF" /> : <ChevronDown size={18} color="#9CA3AF" />}
          </button>

          {formOpen && (
            <form onSubmit={handleCreate} style={s.cardBody}>
              <Field label="Title *" value={title} onChange={setTitle} placeholder="Weekend Special 🎉" />
              <Field label="Description" value={description} onChange={setDescription} placeholder="Get 20% off on all items" />

              <div style={f.wrap}>
                <label style={f.label}>Coupon Code *</label>
                <div style={s.codeRow}>
                  <Tag size={14} color={OG} />
                  <input
                    style={s.codeIn}
                    value={code}
                    onChange={(e) => setCode(e.target.value.toUpperCase())}
                    placeholder="SAVE50"
                  />
                </div>
              </div>

              <div style={f.wrap}>
                <label style={f.label}>Type</label>
                <div style={s.toggle}>
                  {[{ k: 'percent', l: '% Percent' }, { k: 'flat', l: '₹ Flat' }].map((t) => (
                    <button
                      type="button"
                      key={t.k}
                      style={{ ...s.tBtn, ...(discountType === t.k ? { background: OG, borderColor: OG, color: '#fff' } : {}) }}
                      onClick={() => setDiscountType(t.k)}
                    >
                      {t.l}
                    </button>
                  ))}
                </div>
              </div>

              <Field
                label={discountType === 'percent' ? 'Discount % *' : 'Amount ₹ *'}
                value={discountValue}
                onChange={setDiscountValue}
                placeholder={discountType === 'percent' ? '20' : '50'}
                keyboardType="number"
              />

              <div style={{ display: 'flex', gap: 10 }}>
                <div style={{ flex: 1 }}>
                  <Field label="Min Order ₹" value={minOrder} onChange={setMinOrder} placeholder="0" keyboardType="number" />
                </div>
                <div style={{ flex: 1 }}>
                  <Field label="Max Discount ₹" value={maxDiscount} onChange={setMaxDiscount} placeholder="0" keyboardType="number" />
                </div>
              </div>

              {!!code && !!discountValue && (
                <div style={s.preview}>
                  <span style={s.prevCode}>{code}</span>
                  <span style={s.prevArrow}>→</span>
                  <span style={s.prevDisc}>
                    {discountType === 'percent' ? `${discountValue}% OFF` : `₹${discountValue} OFF`}
                  </span>
                </div>
              )}

              <button type="submit" style={{ ...s.createBtn, ...(saving ? { opacity: 0.7 } : {}) }} disabled={saving}>
                <Rocket size={16} color="#fff" />
                <span style={s.createTxt}>&nbsp; {saving ? 'Creating…' : 'Create & Notify Users'}</span>
              </button>
            </form>
          )}
        </div>

        <div style={s.listHead}>
          <span style={s.listTitle}>Active Offers</span>
          <div style={s.badge}><span style={s.badgeTxt}>{offers.length}</span></div>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', marginTop: 24, color: OG }}>Loading…</div>
        ) : offers.length === 0 ? (
          <div style={s.empty}>
            <div style={s.emptyEmoji}>🎟️</div>
            <div style={s.emptyTxt}>No offers yet</div>
          </div>
        ) : (
          offers.map((item) => <OfferCard key={item.id} item={item} onDelete={handleDelete} />)
        )}

      </div>
    </AdminLayout>
  );
}

const f = {
  wrap: { marginBottom: 12 },
  label: { fontSize: 11, fontWeight: 700, color: '#6B7280', marginBottom: 5, letterSpacing: 0.3, display: 'block' },
  input: { width: '100%', boxSizing: 'border-box', background: '#F9FAFB', borderRadius: 10, padding: '11px 12px', fontSize: 14, color: '#111', border: '1px solid #E5E7EB', outline: 'none' },
};

const oc = {
  card: { display: 'flex', alignItems: 'center', background: '#fff', borderRadius: 14, padding: 12, marginBottom: 8, boxShadow: '0 2px 6px rgba(0,0,0,0.05)', border: '1px solid #F3F4F6' },
  left: { flex: 1 },
  codePill: { display: 'inline-block', background: OG_LIGHT, borderRadius: 6, padding: '3px 8px', marginBottom: 4, border: `1px solid ${OG_BORD}` },
  codeText: { fontSize: 11, fontWeight: 900, color: OG, letterSpacing: 1 },
  title: { fontSize: 13, fontWeight: 700, color: '#111' },
  meta: { fontSize: 11, color: '#9CA3AF', marginTop: 2 },
  discWrap: { textAlign: 'center', margin: '0 14px' },
  discVal: { fontSize: 20, fontWeight: 900, color: OG },
  discLbl: { fontSize: 10, fontWeight: 700, color: OG, marginTop: -2 },
  del: { background: '#FEE2E2', border: 'none', borderRadius: 8, padding: 8, cursor: 'pointer', display: 'flex' },
};

const s = {
  card: { background: '#fff', borderRadius: 16, marginBottom: 16, boxShadow: '0 2px 6px rgba(0,0,0,0.05)', border: `1px solid ${OG_BORD}`, overflow: 'hidden' },
  cardHead: { width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: 14, background: OG_LIGHT, border: 'none', borderBottom: `1px solid ${OG_BORD}`, cursor: 'pointer' },
  cardHeadLeft: { display: 'flex', alignItems: 'center', gap: 10 },
  headIcon: { width: 32, height: 32, background: '#fff', borderRadius: 9, display: 'flex', alignItems: 'center', justifyContent: 'center', border: `1px solid ${OG_BORD}` },
  cardTitle: { fontSize: 14, fontWeight: 800, color: '#111', textAlign: 'left' },
  cardSub: { fontSize: 11, color: OG, fontWeight: 600, marginTop: 1, textAlign: 'left' },
  cardBody: { padding: 14 },

  codeRow: { display: 'flex', alignItems: 'center', gap: 8, background: '#F9FAFB', borderRadius: 10, padding: '11px 12px', border: `1.5px solid ${OG_BORD}` },
  codeIn: { flex: 1, fontSize: 15, fontWeight: 800, color: OG, letterSpacing: 2, border: 'none', background: 'transparent', outline: 'none' },

  toggle: { display: 'flex', gap: 8 },
  tBtn: { flex: 1, padding: '10px 0', borderRadius: 10, background: '#F3F4F6', textAlign: 'center', border: '1px solid #E5E7EB', fontSize: 13, fontWeight: 700, color: '#6B7280', cursor: 'pointer' },

  preview: { display: 'flex', alignItems: 'center', gap: 8, background: OG_LIGHT, borderRadius: 10, padding: '9px 12px', marginBottom: 12, border: `1px solid ${OG_BORD}` },
  prevCode: { fontSize: 13, fontWeight: 900, color: OG, letterSpacing: 1 },
  prevArrow: { color: '#9CA3AF', fontWeight: 700 },
  prevDisc: { fontSize: 13, fontWeight: 700, color: '#166534', background: '#DCFCE7', padding: '2px 8px', borderRadius: 6 },

  createBtn: { width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: OG, border: 'none', borderRadius: 12, padding: '14px 0', cursor: 'pointer' },
  createTxt: { color: '#fff', fontSize: 14, fontWeight: 800 },

  listHead: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 },
  listTitle: { fontSize: 13, fontWeight: 800, color: '#374151' },
  badge: { background: OG, borderRadius: 99, minWidth: 24, height: 24, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 7px' },
  badgeTxt: { color: '#fff', fontSize: 11, fontWeight: 800 },

  empty: { textAlign: 'center', padding: '40px 0' },
  emptyEmoji: { fontSize: 40 },
  emptyTxt: { fontSize: 14, color: '#9CA3AF', marginTop: 10, fontWeight: 600 },
};
