import React, { useState } from 'react';
import { ArrowLeft } from 'lucide-react';
import { adminApi } from '../../utils/api';
import { useAdminNavigation } from '../../utils/navigation';
import ProductFormFields from './ProductFormFields';

export default function AdminAddProductScreen() {
  const navigation = useAdminNavigation();
  const [form, setForm] = useState({
    name: '', price: '', unit: 'kg', description: '', image: '',
    stock: '', category: 'Fruits', is_active: true, original_price: '',
  });
  const [saving, setSaving] = useState(false);

  const update = (key, val) => setForm((p) => ({ ...p, [key]: val }));

  const handleSave = async (e) => {
    e.preventDefault();
    if (!form.name.trim() || !form.price) {
      window.alert('Name and Price required!');
      return;
    }
    setSaving(true);
    try {
      await adminApi.post('/products', {
        ...form,
        price: parseFloat(form.price),
        stock: parseFloat(form.stock || '0'),
        original_price: form.original_price ? parseFloat(form.original_price) : null,
      });
      window.alert('✅ Product added!');
      navigation.goBack();
    } catch (e2) {
      window.alert(e2?.response?.data?.detail || 'Failed to add product');
    } finally { setSaving(false); }
  };

  return (
    <div style={{ minHeight: '100vh', background: '#F8F9FA' }}>
      <div style={s.header}>
        <button style={s.backBtn} onClick={() => navigation.goBack()}>
          <ArrowLeft size={20} color="#fff" />
        </button>
        <div>
          <div style={s.headerTitle}>➕ Add Product</div>
          <div style={s.headerSub}>New product add చేయండి</div>
        </div>
      </div>

      <form onSubmit={handleSave} style={{ padding: 16, paddingBottom: 40 }}>
        <div style={s.card}>
          <ProductFormFields form={form} update={update} accent="#22C55E" />
          <button type="submit" style={{ ...s.saveBtn, ...(saving ? { opacity: 0.7 } : {}) }} disabled={saving}>
            {saving ? 'Saving…' : '💾 Save Product'}
          </button>
        </div>
      </form>
    </div>
  );
}

const s = {
  header: { background: '#22C55E', padding: '16px 16px', display: 'flex', alignItems: 'center', gap: 12 },
  backBtn: { width: 38, height: 38, background: 'rgba(255,255,255,0.2)', border: 'none', borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' },
  headerTitle: { fontSize: 17, fontWeight: 900, color: '#fff' },
  headerSub: { fontSize: 11, color: 'rgba(255,255,255,0.8)' },
  card: { background: '#fff', borderRadius: 16, padding: 16, boxShadow: '0 2px 6px rgba(0,0,0,0.06)', maxWidth: 560, margin: '0 auto' },
  saveBtn: { width: '100%', background: '#22C55E', border: 'none', borderRadius: 12, padding: '15px 0', color: '#fff', fontSize: 15, fontWeight: 900, cursor: 'pointer' },
};
