import React, { useEffect, useState, useCallback } from 'react';
import { User, MapPin, UserCircle2 } from 'lucide-react';
import AdminLayout from './AdminLayout';
import WhatsAppIcon from '../../components/WhatsAppIcon';
import { adminApi } from '../../utils/api';
import { useAdminNavigation } from '../../utils/navigation';

const STATUS_COLOR = {
  Pending: '#fd9644',
  Assigned: '#3498db',
  OutForDelivery: '#a55eea',
  Delivered: '#20bf6b',
  Cancelled: '#ef4444',
};

export default function AdminOrdersScreen() {
  const navigation = useAdminNavigation();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const r = await adminApi.get('/orders');
      setOrders(r.data || []);
    } catch {
      navigation.replace('AdminLogin');
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => { load(); }, [load]);

  const updateStatus = async (orderId, newStatus) => {
    const prev = orders;
    // optimistic update — UI immediately reflect avutundi
    setOrders((os) => os.map((o) => (o.id === orderId ? { ...o, status: newStatus } : o)));
    try {
      await adminApi.put(`/orders/${orderId}/status`, { status: newStatus });
    } catch {
      setOrders(prev); // fail అయితే revert
      window.alert('Status update failed');
    }
  };

  const sendWhatsAppMessage = (order) => {
    if (!order?.user?.phone) {
      window.alert('User phone number not available!');
      return;
    }

    const message = `Hello ${order.user.name || 'Sir/Madam'},

✅ *Your Order has been Confirmed!*

*Order ID:* #${order.id}
*Items:* ${order.items?.map((item) => `${item.name} x${item.qty}`).join(', ') || 'N/A'}
*Total Amount:* ₹${Number(order.total).toFixed(0)}
*Status:* ${order.status}
*Date:* ${order.created_at || '---'}

Thank you for shopping with us!
Our delivery partner will reach you soon.

For any queries contact us.`;

    const phone = order.user.phone.replace(/[^0-9]/g, '');
    const url = `https://wa.me/91${phone}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const stats = [
    { label: 'Total', value: orders.length, color: '#6366f1' },
    { label: 'Pending', value: orders.filter((o) => o.status === 'Pending').length, color: '#fd9644' },
    { label: 'Active', value: orders.filter((o) => o.status === 'OutForDelivery').length, color: '#a55eea' },
    { label: 'Delivered', value: orders.filter((o) => o.status === 'Delivered').length, color: '#20bf6b' },
  ];

  return (
    <AdminLayout activeScreen="AdminOrders">
      {loading ? (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%' }}>Loading…</div>
      ) : (
        <div style={{ padding: 16, paddingBottom: 40 }}>
          <div style={s.pageHeader}>
            <div style={s.pageTitle}>🛒 All Orders</div>
            <div style={s.livePill}>
              <div style={s.liveDot} />
              <span style={s.liveTxt}>LIVE</span>
            </div>
          </div>

          <div style={s.statsGrid}>
            {stats.map((st) => (
              <div key={st.label} style={{ ...s.statCard, borderLeftColor: st.color }}>
                <div style={s.statVal}>{st.value}</div>
                <div style={s.statLbl}>{st.label}</div>
              </div>
            ))}
          </div>

          {orders.length === 0 ? (
            <div style={s.empty}>
              <div style={{ fontSize: 40 }}>📭</div>
              <div style={s.emptyTxt}>No orders yet</div>
            </div>
          ) : orders.map((o) => (
            <div key={o.id} style={s.card}>
              <div style={s.cardHeader}>
                <div style={s.idBadge}><span style={s.idTxt}>#{o.id}</span></div>
                <span style={s.timeText}>{o.created_at || ''}</span>
                <select
                  value={o.status}
                  onChange={(e) => updateStatus(o.id, e.target.value)}
                  style={{ ...s.statusSelect, background: STATUS_COLOR[o.status] || '#94a3b8' }}
                >
                  {Object.keys(STATUS_COLOR).map((st) => (
                    <option key={st} value={st}>{st}</option>
                  ))}
                </select>
              </div>

              <div style={s.row}>
                <User size={14} color="#6B7280" />
                <span style={s.val}>{o.user?.name}</span>
                <span style={s.phone}>{o.user?.phone}</span>
              </div>

              <div style={s.row}>
                <MapPin size={14} color="#6B7280" />
                <span style={{ ...s.val, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {o.address || '—'}
                </span>
              </div>

              <div style={s.row}>
                <UserCircle2 size={14} color="#6B7280" />
                {o.worker
                  ? <span style={{ ...s.val, color: '#6366f1' }}>🛵 {o.worker?.name}</span>
                  : <span style={{ ...s.val, color: '#9CA3AF', fontStyle: 'italic' }}>Not assigned</span>}
              </div>

              {(o.items || []).length > 0 && (
                <div style={s.itemsWrap}>
                  {o.items.map((item, i) => (
                    <div key={i} style={s.itemChip}>
                      <span style={s.itemTxt}>{item.name} ×{item.qty}</span>
                    </div>
                  ))}
                </div>
              )}

              <div style={s.totalRow}>
                <span style={s.totalLbl}>Total</span>
                <span style={s.totalVal}>₹{Number(o.total).toFixed(2)}</span>
              </div>

              <button style={s.whatsappButton} onClick={() => sendWhatsAppMessage(o)}>
                <WhatsAppIcon size={20} />
                <span style={s.whatsappButtonText}>Send WhatsApp Message</span>
              </button>
            </div>
          ))}
        </div>
      )}
    </AdminLayout>
  );
}

const s = {
  pageHeader: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 },
  pageTitle: { fontSize: 18, fontWeight: 800, color: '#111' },
  livePill: { display: 'flex', alignItems: 'center', gap: 5, background: '#ECFDF5', borderRadius: 99, padding: '4px 10px' },
  liveDot: { width: 7, height: 7, borderRadius: 99, background: '#10b981' },
  liveTxt: { fontSize: 10, fontWeight: 700, color: '#10b981' },
  statsGrid: { display: 'flex', flexWrap: 'wrap', gap: 10, marginBottom: 20 },
  statCard: { width: 'calc(47% - 5px)', background: '#fff', borderRadius: 12, padding: 14, borderLeft: '4px solid', boxShadow: '0 2px 6px rgba(0,0,0,0.05)', boxSizing: 'border-box' },
  statVal: { fontSize: 24, fontWeight: 900, color: '#111' },
  statLbl: { fontSize: 10, fontWeight: 700, color: '#64748B', textTransform: 'uppercase', marginTop: 2 },
  card: { background: '#fff', borderRadius: 14, padding: 14, marginBottom: 10, boxShadow: '0 2px 6px rgba(0,0,0,0.05)', border: '1px solid #F3F4F6' },
  cardHeader: { display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 },
  idBadge: { background: '#F1F5F9', borderRadius: 7, padding: '4px 9px' },
  idTxt: { fontSize: 12, fontWeight: 800, color: '#334155' },
  timeText: { fontSize: 11, color: '#9CA3AF', flex: 1 },
  statusPill: { borderRadius: 99, padding: '4px 10px' },
  statusTxt: { fontSize: 10, fontWeight: 800, color: '#fff', textTransform: 'uppercase' },
  statusSelect: {
    borderRadius: 99, padding: '4px 10px', fontSize: 10, fontWeight: 800, color: '#fff',
    textTransform: 'uppercase', border: 'none', cursor: 'pointer', outline: 'none', appearance: 'auto',
  },
  row: { display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 },
  val: { fontSize: 13, fontWeight: 600, color: '#111' },
  phone: { fontSize: 12, color: '#64748B', marginLeft: 4 },
  itemsWrap: { display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 8, marginBottom: 8 },
  itemChip: { background: '#F0FDF4', borderRadius: 6, padding: '3px 8px' },
  itemTxt: { fontSize: 11, color: '#166534', fontWeight: 600 },
  totalRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid #F3F4F6', paddingTop: 10, marginTop: 4 },
  totalLbl: { fontSize: 13, color: '#6B7280', fontWeight: 600 },
  totalVal: { fontSize: 16, fontWeight: 800, color: '#22C55E' },
  whatsappButton: { background: '#25D366', border: 'none', marginTop: 12, padding: '12px 0', borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, width: '100%', cursor: 'pointer' },
  whatsappButtonText: { color: '#fff', fontSize: 15, fontWeight: 700 },
  empty: { textAlign: 'center', padding: 40, background: '#fff', borderRadius: 14 },
  emptyTxt: { fontSize: 15, color: '#9CA3AF', marginTop: 8 },
};
