import React, { useEffect, useState, useCallback } from 'react';
import { Plus, Pencil, Trash2 } from 'lucide-react';
import AdminLayout from './AdminLayout';
import { adminApi } from '../../utils/api';
import { useAdminNavigation } from '../../utils/navigation';

export default function AdminProductsScreen() {
  const navigation = useAdminNavigation();
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const r = await adminApi.get('/products');
      setProducts(r.data || []);
    } catch { /* noop */ }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleDelete = (id) => {
    if (!window.confirm('ఈ product delete చేయాలా?')) return;
    adminApi.delete(`/products/${id}`).then(load).catch(() => window.alert('Delete failed'));
  };

  return (
    <AdminLayout activeScreen="AdminProducts">
      {loading ? (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%' }}>Loading…</div>
      ) : (
        <div style={{ padding: 16, paddingBottom: 40 }}>
          <div style={s.pageHeader}>
            <div style={s.pageTitle}>🍎 Products ({products.length})</div>
            <button style={s.addBtn} onClick={() => navigation.navigate('AdminAddProduct')}>
              <Plus size={18} color="#fff" />
              <span style={s.addBtnTxt}>Add</span>
            </button>
          </div>

          {products.length === 0 ? (
            <div style={s.empty}>
              <div style={{ fontSize: 40 }}>🍎</div>
              <div style={s.emptyTxt}>No products yet</div>
              <button style={s.addBtn} onClick={() => navigation.navigate('AdminAddProduct')}>
                <span style={s.addBtnTxt}>Add First Product</span>
              </button>
            </div>
          ) : products.map((p) => (
            <div key={p.id} style={s.card}>
              <img
                src={p.image || 'https://cdn-icons-png.flaticon.com/512/1625/1625028.png'}
                alt={p.name}
                style={s.productImg}
              />
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <span style={s.productName}>{p.name}</span>
                  <div style={{ ...s.activeBadge, background: p.is_active ? '#DCFCE7' : '#FEE2E2' }}>
                    <span style={{ ...s.activeTxt, color: p.is_active ? '#166534' : '#991B1B' }}>
                      {p.is_active ? 'Active' : 'Inactive'}
                    </span>
                  </div>
                </div>
                <div style={s.productPrice}>₹{p.price} / {p.unit}</div>
                <div style={s.productCat}>{p.category}</div>
                <div style={s.cardActions}>
                  <button style={s.editBtn} onClick={() => navigation.navigate('AdminEditProduct', { product: p })}>
                    <Pencil size={13} color="#3B82F6" />
                    <span style={s.editBtnTxt}>Edit</span>
                  </button>
                  <button style={s.deleteBtn} onClick={() => handleDelete(p.id)}>
                    <Trash2 size={13} color="#EF4444" />
                    <span style={s.deleteBtnTxt}>Delete</span>
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </AdminLayout>
  );
}

const s = {
  pageHeader: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 },
  pageTitle: { fontSize: 18, fontWeight: 800, color: '#111' },
  addBtn: { display: 'flex', alignItems: 'center', gap: 4, background: '#22C55E', border: 'none', borderRadius: 10, padding: '8px 14px', cursor: 'pointer' },
  addBtnTxt: { color: '#fff', fontSize: 13, fontWeight: 700 },
  card: { background: '#fff', borderRadius: 14, padding: 12, marginBottom: 10, boxShadow: '0 2px 6px rgba(0,0,0,0.05)', display: 'flex', gap: 12, border: '1px solid #F3F4F6' },
  productImg: { width: 70, height: 70, borderRadius: 12, background: '#F0FDF4', objectFit: 'contain', flexShrink: 0 },
  productName: { fontSize: 14, fontWeight: 800, color: '#111', flex: 1, marginRight: 8 },
  productPrice: { fontSize: 13, fontWeight: 700, color: '#22C55E', marginTop: 4 },
  productCat: { fontSize: 11, color: '#9CA3AF', marginTop: 2 },
  activeBadge: { borderRadius: 6, padding: '3px 8px', flexShrink: 0 },
  activeTxt: { fontSize: 10, fontWeight: 700 },
  cardActions: { display: 'flex', gap: 8, marginTop: 10 },
  editBtn: { display: 'flex', alignItems: 'center', gap: 4, background: '#EFF6FF', border: 'none', borderRadius: 8, padding: '6px 10px', cursor: 'pointer' },
  editBtnTxt: { fontSize: 12, color: '#3B82F6', fontWeight: 700 },
  deleteBtn: { display: 'flex', alignItems: 'center', gap: 4, background: '#FEE2E2', border: 'none', borderRadius: 8, padding: '6px 10px', cursor: 'pointer' },
  deleteBtnTxt: { fontSize: 12, color: '#EF4444', fontWeight: 700 },
  empty: { textAlign: 'center', padding: 40, background: '#fff', borderRadius: 14, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12 },
  emptyTxt: { fontSize: 15, color: '#9CA3AF' },
};
